def apply_scene_off_lighting_isolation_console_commands(game):
    state = {
        "commands": [],
        "applied": 0,
    }
    try:
        player_controller = get_player_controller(game=game)
    except Exception as exc:
        state["error"] = str(exc)
        return state

    for show_flag_name in SCENE_OFF_LIGHTING_ISOLATION_SHOW_FLAGS:
