def get_scene_light_render_groups(light_settings):
    scene_on_settings = []
    scene_off_settings = []
    for setting in light_settings:
        if get_light_setting_scene_lights_enabled(setting=setting):
            scene_on_settings.append(setting)
        else:
            scene_off_settings.append(setting)

    groups = []
